.rd-disk::before,
.rd-disk::after {
      content: '';
      position: absolute;
      background: rgba(34, 197, 94, 0.4);
    }
.rd-disk::before {
      left: 50%;
      top: 0;
      bottom: 0;
      width: 1px;
    }
.rd-disk::after {
      top: 50%;
      left: 0;
      right: 0;
      height: 1px;
    }
$on .rd-disk {
      transform: translateX(70px);
      border-color: #4ade80;
      box-shadow: 0 0 14px rgba(74, 222, 128, 0.7);
    }
.rd-sweep {
      position: absolute;
      inset: 0;
      border-radius: 50%;
      background: conic-gradient(from 0deg, rgba(74, 222, 128, 0) 0deg, rgba(74, 222, 128, 0.85) 70deg, rgba(74, 222, 128, 0) 71deg);
      opacity: 0;
      z-index: 2;
      transition: opacity 0.3s ease;
    }
$on .rd-sweep {
      opacity: 1;
      animation: KF_sweep 1.6s linear infinite;
    }
.rd-blips i {
      position: absolute;
      width: 5px;
      height: 5px;
      border-radius: 50%;
      background: #86efac;
      box-shadow: 0 0 6px #4ade80;
      opacity: 0;
    }
.rd-blips i:nth-child(1) { top: 14px; left: 30px; }
.rd-blips i:nth-child(2) { top: 36px; left: 52px; }
.rd-blips i:nth-child(3) { top: 22px; left: 74px; }
$on .rd-blips i {
      animation: KF_blip 1.6s ease-out infinite;
    }
$on .rd-blips i:nth-child(2) { animation-delay: 0.5s; }
$on .rd-blips i:nth-child(3) { animation-delay: 1s; }
@keyframes KF_sweep {
      from { transform: rotate(0deg); }
      to { transform: rotate(360deg); }
    }
@keyframes KF_blip {
      0% { opacity: 1; transform: scale(1.6); }
      100% { opacity: 0; transform: scale(0.6); }
    }
